# -*- coding: utf-8 -*-
"""Великобритания: темы законов (DE_TOPICS), теги отношений (LAW_TAGS), фундаментальные темы (DE_FUND_ADD)."""
from gb_base import PK, GK

TOPICS = []
TAGS = {}
FUND = []

def _pk(d):
    return {PK[k]: float(v) for k, v in d.items()} if d else None

def _gk(d):
    return {GK.get(k, k): float(v) for k, v in d.items()} if d else None

def V(n, d, c=None, s=None, a=None, st=None, rg=None, set=None, ps=None, tag=None):
    v = {"n": n, "d": d}
    if c is not None: v["c"] = float(c)
    if a: v["a"] = {k: float(x) for k, x in a.items()}
    if s: v["s"] = _gk(s)
    if st: v["st"] = {k: float(x) for k, x in st.items()}
    if rg: v["rg"] = {k: float(x) for k, x in rg.items()}
    if set: v["set"] = {k: (x if isinstance(x, int) else float(x)) for k, x in set.items()}
    if ps: v["ps"] = _pk(ps)
    v["_tag"] = tag
    return v

def T(tid, cat, name, desc, vs, fund=False):
    out = []
    for i, v in enumerate(vs):
        tg = v.pop("_tag", None)
        if tg: TAGS.setdefault(tid, {})[i] = [tg[0], tg[1]]
        out.append(v)
    TOPICS.append({"id": tid, "cat": cat, "name": name, "desc": desc, "v": out})
    if fund: FUND.append(tid)

